using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;using MapSharedProps.EditorTools;
public static class Silver95Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string input,string folder){if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets",folder.Substring(7));var d=new Dictionary<string,GameObject>();var root=new GameObject("Temporary placements");SmallPropsV1.Build(input,folder,root.transform,Shader.Find("MapSharedProps/Lit"),d);UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();Check(d.Count==43,"43 prefabs");return d;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence95Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var p=Build(Path.Combine(Root,"Input95"),"Assets/Imported95");var s=p["treasurechest_silver"];var old=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported92/small-treasurechest_silver.prefab");Check(s.GetComponent<MeshCollider>().sharedMesh==old.GetComponent<MeshCollider>().sharedMesh,"silver collider exact");Check(s.GetComponent<MeshFilter>().sharedMesh==old.GetComponent<MeshFilter>().sharedMesh,"round silver shape exact");Check(s.transform.Find("Bounded seam light and motes").GetComponent<MeshFilter>().sharedMesh.vertexCount==36,"nine silver motes");Check(p["treasurechest_gold"].transform.Find("Bounded seam light and motes").GetComponent<MeshFilter>().sharedMesh.vertexCount==72,"eighteen gold motes");
 var silver=(GameObject)PrefabUtility.InstantiatePrefab(s);var gold=(GameObject)PrefabUtility.InstantiatePrefab(p["treasurechest_gold"]);var cam=new GameObject("Budget camera").AddComponent<Camera>();cam.tag="MainCamera";cam.transform.position=new Vector3(0,2,-6);foreach(var o in new[]{silver,gold}){o.GetComponent<ChestPresentation>().SetSeed("same-seed");o.GetComponent<ChestPresentation>().SetTime(.8f);}ChestPresentation.RefreshLights(cam);var sl=silver.GetComponentsInChildren<Light>();var gl=gold.GetComponentsInChildren<Light>();Check(sl.Length==2&&gl.Length==2,"two cluster lights each");for(int k=0;k<2;k++){Check(Mathf.Abs(sl[k].intensity/gl[k].intensity-.6f)<.0001f,"60 percent light intensity");Check(sl[k].color==new Color(.85f,.95f,1),"silver light colour");}var objects=new List<GameObject>{silver,gold};for(int k=0;k<6;k++){var o=(GameObject)PrefabUtility.InstantiatePrefab(p[k%2==0?"treasurechest_silver":"treasurechest_gold"]);o.transform.position=new Vector3(k*.5f,0,0);o.GetComponent<ChestPresentation>().SetTime(.8f);objects.Add(o);}ChestPresentation.RefreshLights(cam);Check(objects.Sum(o=>o.GetComponentsInChildren<Light>().Count(l=>l.enabled))==8,"shared gold/silver eight light limit");foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);UnityEngine.Object.DestroyImmediate(cam.gameObject);
 foreach(string kind in new[]{"absent","bad"}){var q=Build(Path.Combine(Root,"Input95-"+kind),"Assets/Imported95-"+kind);Check(!q["treasurechest_silver"].GetComponent<ChestPresentation>(),"optional silver fallback "+kind);Check(q["treasurechest_gold"].transform.Find("Bounded seam light and motes").GetComponent<MeshFilter>().sharedMesh.vertexCount==72,"gold V2 retained "+kind);Check(q["treasurechest_rainbow"].GetComponent<ChestSanctumPresentation>(),"rainbow retained "+kind);}
 File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"prefabsPerCase\":43,\"cases\":[\"normal\",\"absent\",\"invalidSilver\"],\"silverMotes\":9,\"goldMotes\":18,\"silverLightPowerRatio\":0.6,\"silverGeometryColliderExact\":true,\"sharedGoldSilverActiveLightCap\":8,\"rainbowCapUnchanged\":6,\"playerExecuted\":false}");}catch(Exception ex){Debug.LogException(ex);File.WriteAllText(Path.Combine(output,"error.txt"),ex.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
